const code = Number(msg.statusCode || 0);
const result = msg.payload;
const accepted = code >= 200 && code < 300 && result && typeof result === "object" && typeof result.client?.id === "string" && result.client.id.length > 0 && typeof result.dialog?.id === "string" && result.dialog.id.length > 0;
msg.headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
if (accepted) {
  msg.statusCode = 200;
  // The current support API confirms processing, not durable Mongo custody.
  msg.payload = { ok: true, accepted: true, persistenceConfirmed: false };
} else {
  msg.statusCode = code === 400 || code === 422 ? 400 : code === 409 ? 409 : code === 429 || code === 503 ? 503 : code === 504 ? 504 : 502;
  msg.payload = { ok: false, accepted: false, code: "SUPPORT_INGEST_NOT_CONFIRMED" };
}
return msg;

const base = String(env.get("SUPPORT_API_BASE_URL") || "http://localhost:3000/api").replace(/\/+$/, "");
const token = String(env.get("SUPPORT_INTEGRATION_TOKEN") || "").trim();

const raw = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};

function norm(value) {
  const text = String(value ?? "").trim();
  if (!text) return undefined;
  const lowered = text.toLowerCase();
  if (lowered === "null" || lowered === "undefined") return undefined;
  return text;
}

const externalUserId =
  norm(raw.externalUserId) ||
  norm(raw.userId) ||
  norm(raw.clientId) ||
  norm(raw.senderId) ||
  norm(raw.channelUserId);

const externalChatId =
  norm(raw.externalChatId) ||
  norm(raw.externalThreadId) ||
  norm(raw.chatId) ||
  norm(raw.threadId) ||
  norm(raw.dialogId);

const payload = {
  connector: "LK_ACADEMY_WEB_MESSENGER",
  externalUserId,
  externalChatId,
  externalMessageId: raw.externalMessageId,
  timestamp: raw.timestamp,
  displayName: norm(raw.displayName) || norm(raw.clientName) || norm(raw.senderName),
  username: norm(raw.username),
  phone: norm(raw.phone) || norm(raw.primaryPhone),
  email: norm(raw.email),
  stationId: norm(raw.stationId),
  stationName: norm(raw.stationName),
  selectedStationId: norm(raw.selectedStationId) || norm(raw.stationId),
  selectedStationName: norm(raw.selectedStationName) || norm(raw.stationName),
  subject: norm(raw.subject),
  text: norm(raw.text) || norm(raw.message) || norm(raw.content),
  eventType: norm(raw.eventType),
  direction: norm(raw.direction) || "INBOUND",
  kind: norm(raw.kind),
  meta: {
    source: "lk_academy",
    receivedAt: new Date().toISOString(),
    payload: raw
  }
};

if (!payload.externalUserId && !payload.externalChatId && !payload.phone && !payload.email) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
  msg.payload = { ok: false, accepted: false, code: "LK_ACADEMY_IDENTIFIERS_REQUIRED" };
  return [null, msg];
}

msg.method = "POST";
msg.url = base + "/support/dialogs/events";
msg.requestTimeout = 8000;
msg.followRedirects = false;
msg.headers = { "Content-Type": "application/json" };
if (token) {
  msg.headers["x-integration-token"] = token;
}
msg.payload = payload;
return [msg, null];

msg.statusCode = 503;
msg.headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
msg.payload = { ok: false, accepted: false, code: "SUPPORT_INGEST_NOT_CONFIRMED" };
return msg;
